    wy_skin_specular_base(baseColor, diffuseColor, N, V, opacity, neutralRamp.a,
      skinSelfShadow, sceneShadow, face, faceMask, specMask,
      wb_SkinSpecularViewRange, wb_SkinSpecularRange, wb_SkinSpecularIntensity,
      wb_SkinSpecularColor.rgb, wb_SkinSpecularDarkBrightness,
      wb_FaceSpecularIntensityBias, tempBase, tempDiffuse, skinSpec, specBrightness);
